// by hand (#771, founder directive 2026-08-30: "Go for the generated per-actor enum").
//
// ONE `<Actor>Inbox` enum per mailbox actor: the CLOSED set of messages that actor's single queue
// can carry, spanning COMMAND / inbound FACT / REMINDER, each variant carrying its typed payload.
//
// THIS FILE IS THE ENUM ONLY. The routing `match` — what a message DOES — is HUMAN-OWNED, in
// `crates/infrastructure/src/inbox.rs`. Generating both halves from one walk would make the match
// exhaustive by construction and the compiler would catch nothing; keeping them apart is what makes
// a new `receives:` entry an E0004 compile error instead of a `FAILED` row in production (#595).
//
// The wire stays a string: `ActorInbox::parse(actor_type, message_type, payload)` is the single
// fallible edge, and it consumes the ACTOR TYPE as well as the message type — so a row enqueued on
// lane A carrying lane B's message cannot parse at all (ADR-20260829-230418, "Aggregates own the
// facts": the transport must not be able to violate the isolation the aggregates declare).

/// What kind of message an inbox variant carries. The inbox is ONE queue, so one type spans all
/// three; the kind is a property of the variant, never a second enum to keep in sync.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InboxKind {
    /// A `commands.yaml#/…` entry: write-side input, may be REJECTED.
    Command,
    /// An `events.yaml#/…` entry: a fact that already happened, recorded — never rejected.
    Fact,
    /// A `#/<Actor>/reminders/<Name>` entry: a reminder this actor scheduled for itself, promoted
    /// to the queue when due (its payload is the declared fact, ADR-20260731-153000 §1a).
    Reminder,
}

/// Why a wire triple could not become a typed inbox value.
///
/// The three arms are DELIBERATELY distinct, because the runtime owes them different postures:
/// `UnknownActor` and `UndeclaredMessage` are TRANSIENT (a rolling deploy legitimately produces
/// them — retry, then park loudly), while `Payload` is a genuine shape failure of a message this
/// build does understand.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum InboxParseError {
    /// No mailbox actor by this `actor_type` exists in THIS build.
    UnknownActor { actor_type: String },
    /// The actor exists and does not declare this message in its `receives:` set — in THIS build.
    UndeclaredMessage { actor_type: &'static str, message_type: String },
    /// A DECLARED message whose payload does not deserialize into its typed shape.
    Payload { actor_type: &'static str, message_type: &'static str, detail: String },
}

impl InboxParseError {
    /// TRANSIENT means: this build cannot route the row, but a build on the other side of a rolling
    /// deploy can — so the row must be RETRIED and then PARKED (the poison path), never terminally
    /// FAILED. Terminal-failing an unknown type during a deploy buries a paid order.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::UnknownActor { .. } | Self::UndeclaredMessage { .. })
    }
}

impl std::fmt::Display for InboxParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::UnknownActor { actor_type } => {
                write!(f, "no mailbox actor '{actor_type}' in this build")
            }
            Self::UndeclaredMessage { actor_type, message_type } => write!(
                f,
                "actor '{actor_type}' does not declare message '{message_type}' in this build"
            ),
            Self::Payload { actor_type, message_type, detail } => {
                write!(f, "{actor_type}/{message_type} payload: {detail}")
            }
        }
    }
}

impl std::error::Error for InboxParseError {}

